trait Dist[A] { def at(a: A, i: Int): Int }

given Dist[Vector[Int]] with
  def at(a: Vector[Int], i: Int) = a(i)              // O(1)

given Dist[List[Int]] with
  def at(a: List[Int], i: Int) = a.drop(i).head      // O(n)

def nth[A](a: A, i: Int)(using d: Dist[A]): Int = d.at(a, i)   // chosen at compile time
